CREATE TABLE IF NOT EXISTS accounts (id SERIAL PRIMARY KEY, username TEXT UNIQUE NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS products (id SERIAL PRIMARY KEY, name TEXT NOT NULL, price NUMERIC(10,2) NOT NULL, description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS lab_users (id SERIAL PRIMARY KEY, username TEXT NOT NULL, email TEXT NOT NULL, department TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS books (id SERIAL PRIMARY KEY, title TEXT NOT NULL, author TEXT NOT NULL, publication_year INT NOT NULL, available BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS shipments (id SERIAL PRIMARY KEY, tracking_number TEXT UNIQUE NOT NULL, status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reviews (id SERIAL PRIMARY KEY, product_id INT REFERENCES products(id), reviewer_name TEXT NOT NULL, review_text TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT now());

